#!/usr/bin/env bash
set -euo pipefail
write_gzip_b64() {
  local path="$1"
  local payload="$2"
  mkdir -p "$(dirname "$path")"
  printf '%s' "$payload" | base64 -d | gzip -d > "$path"
}
